effect.shader:
const float PI = 3.14159265;

float canal(vec2 uv, vec2 c, float ang, int k, int n) {
    vec2 p = uv - c; p.x *= acAspect;
    float r = length(p);
    float a0 = atan(p.y, p.x);
    float s = 0.0;
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = (float(i)/float(n) - 0.5) * ang * PI / 180.0;
        vec2 q = vec2(cos(a0 + t), sin(a0 + t)) * r;
        q.x /= acAspect;
        s += texture(inputImg, c + q).rgb[k];
    }
    return s / float(n + 1);
}

void main() {
    vec4 o = texture(inputImg, acScreenNorm);
    if (angle <= 0.0) { fragColor = o; return; }
    int n = clamp(int(samples), 4, 48);
    float r = canal(acScreenNorm, center, angle * (1.0 + chroma * 0.1), 0, n);
    float g = canal(acScreenNorm, center, angle,                           1, n);
    float b = canal(acScreenNorm, center, angle * (1.0 - chroma * 0.1), 2, n);
    fragColor = vec4(r, g, b, o.a);
}
